Q: How can a connection to an OPC UA Module be established? A: <p>Here is a code that logs OPC Unified Architecture data changes into an SQL database, using a subscription. It is made with the <a href="https://www.opclabs.com/products/quickopc" rel="nofollow noreferrer">QuickOPC library</a> (disclaimer: my work). The code is taken&amp;slightly modified from <a href="https://www.doc-that.com/files/onlinedocs/OPCLabs-ConnectivityStudio/Latest/User%27s%20Guide%20and%20Reference-Connectivity%20Software/webframe.html#Installed%20Examples%20-%20Client%20Console%20-%20UASimpleLogToSql.html" rel="nofollow noreferrer">the doc</a>.</p>
<pre><code>using System;
using System.Data;
using System.Data.SqlClient;
using System.Data.SqlTypes;
using System.Diagnostics;
using System.Threading;
using OpcLabs.EasyOpc.UA;

namespace UASimpleLogToSql
{
    class Program
    {
        static void Main()
        {
            const string connectionString =
                &quot;Data Source=(local);Initial Catalog=QuickOPCExamples;Integrated Security=true&quot;;

            // Define which server we will work with.
            UAEndpointDescriptor endpointDescriptor =
                &quot;opc.tcp://opcua.demo-this.com:51210/UA/SampleServer&quot;;

            Console.WriteLine(&quot;Starting up...&quot;);
            using (var connection = new SqlConnection(connectionString))
            {
                connection.Open();

                // Create all necessary ADO.NET objects.
                var adapter = new SqlDataAdapter(&quot;SELECT * FROM UASimpleLog&quot;, connection);
                var dataSet = new DataSet();
                adapter.FillSchema(dataSet, SchemaType.Source, &quot;UASimpleLog&quot;);
                adapter.InsertCommand = new SqlCommandBuilder(adapter).GetInsertCommand();
                DataTable table = dataSet.Tables[&quot;UASimpleLog&quot;];
                Debug.Assert(!(table is null));

                Console.WriteLine(&quot;Logging for 30 seconds...&quot;);
                // Subscribe to an OPC item, using an anonymous method to process the notifications.
                int handle = EasyUAClient.SharedInstance.SubscribeDataChange(
                    endpointDescriptor,
                    &quot;nsu=http://test.org/UA/Data/ ;i=10853&quot;,
                    100,
                    (_, eventArgs) =&gt;
                    {
                        Debug.Assert(!(eventArgs is null));
                        Console.Write(&quot;.&quot;);

                        // In this example, we only log valid data. Production logger would also log errors.
                        if (!(eventArgs.AttributeData is null))
                        {
                            // Fill a DataRow with the OPC data, and add it to a DataTable.
                            Debug.Assert(!(table.Rows is null));
                            table.Rows.Clear();
                            DataRow row = table.NewRow();
                            row[&quot;NodeID&quot;] = eventArgs.Arguments.NodeDescriptor.NodeId;
                            row[&quot;Value&quot;] = eventArgs.AttributeData.Value;
                            row[&quot;SourceTimestamp&quot;] = (eventArgs.AttributeData.SourceTimestamp &lt; (DateTime)SqlDateTime.MinValue)
                                                   ? (DateTime)SqlDateTime.MinValue
                                                   : eventArgs.AttributeData.SourceTimestamp;
                            row[&quot;ServerTimestamp&quot;] = (eventArgs.AttributeData.ServerTimestamp &lt; (DateTime)SqlDateTime.MinValue)
                                                   ? (DateTime)SqlDateTime.MinValue
                                                   : eventArgs.AttributeData.ServerTimestamp;
                            row[&quot;StatusCode&quot;] = eventArgs.AttributeData.StatusCode.InternalValue;

                            Debug.Assert(!(table.Rows is null));
                            table.Rows.Add(row);

                            // Update the underlying DataSet using an insert command.
                            adapter.Update(dataSet, &quot;UASimpleLog&quot;);
                        }
                    }
                    );
                Thread.Sleep(30 * 1000);
                Console.WriteLine();

                Console.WriteLine(&quot;Shutting down...&quot;);
                EasyUAClient.SharedInstance.UnsubscribeMonitoredItem(handle);
            }

            Console.WriteLine(&quot;Finished.&quot;);
        }
    }
}
</code></pre>

Q: Microsoft Calendar Authorization Expiration Issue A: <p>I think your refresh token doesn't work efficiently.</p>
<p>You can fetch it by using this code:</p>
<pre><code>const response = await fetch(OAUTH_ENDPOINTS.microsoft.token, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: body.toString(),
});
</code></pre>

Q: How can I change a day&#39;s background color in the week view of Thunderbird calendar? A: <p>To change the color of the Today column (i.e., the entire day), in week view and in day view, use the css term  <em><strong>.multiday-hour-box</strong></em> preceded by <em><strong>.day-column-today</strong></em></p>
<p>For example, the code below applies to day view and week view (not to month / multiweek), and changes Today's header to yellow, and Today's content area (the whole column) to a paler yellow.</p>
<pre><code>/* Highlight current day-of-week in the week view HEADER (which shows the date) */
.day-column-today .day-column-heading {
  background-color: yellow !important;
}

/* today bg color for week view content area */
.day-column-today .multiday-hour-box {
  background-color: #fbffa0 !important; /* A lighter shade of yellow for the main area */
}
</code></pre>

Q: How to attach middleware to an existing named route from a package in laravel 5? A: <p>You can add this to your AppServiceProvider::boot()</p>
<pre class="lang-php prettyprint-override"><code>        /** {@see Router::dispatchToRoute()}. */
        \Route::matched(function(RouteMatched $event) {
            if ($event-&gt;route-&gt;getName() === 'the.route.name') {
                $event-&gt;route-&gt;middleware('whatever-extra-middleware');
            }
        });
</code></pre>
<p>You could also use <code>$event-\&gt;route-\&gt;named('something.with.wildcard.\*')</code> or other neat stuff (checkout <code>vendor/laravel/framework/src/Illuminate/Routing/Route.php</code>).</p>
